    "id": "r-feedback-3",
    "kind": "reading",
    "level": 5,
    "passage": "有一位客户打电话来，说他收到的商品与自己要的不一样。员工本来想马上说明公司的规定，但是经理提醒他，应该先听清楚客户的问题，再寻找解决办法。员工听完后发现，客户并不是想得到更低的价格，而是希望尽快收到正确的商品。他们最后解决了问题，客户也表示满意。",
    "title": "A customer's complaint",
    "translation": "A customer called because the goods received were different from what he wanted. The employee planned to explain the rules immediately, but the manager reminded him to listen first and then find a solution. After listening, the employee realized the customer wanted the correct goods quickly, not a lower price. They solved the problem and the customer was satisfied.",
