  "passageId": "r-science-memory",
  "passageLevel": 5,
  "title": "Science: Why testing yourself helps",
  "passage": "两个学生用不同的方法学习。一个学生把书看了三遍，另一个学生只看一遍，然后把书放在一边，试着回答自己提出的问题。过了一天，老师让他们再回答同样的问题。只看了一遍书的学生发现，虽然学习时觉得比较难，但自己记得更清楚。这个故事提醒我们，学习不只是看到答案，还要试着自己想出答案。",
