  "title": "Mystery · 1: A letter from tomorrow",
  "passage": "一个学生在图书馆的书里发现了一张纸。上面写着：“明天下午三点，请到学校门口等我。”他不知道是谁写的，也不明白为什么有人知道他会看到这张纸。过了一天，他按时来到学校门口。等了半个小时，一个女学生走过来，问他：“你也看到那张纸了吗？”",
