  "passage": "女学生拿出自己的那张纸。学生发现，两张纸上的内容完全一样。他们决定一起回图书馆找那本书。一位老师正在门口等着他们。老师笑着说：“我为了让学生认识新朋友，在不同的书里放了一些纸。你们是今天最早来的人。”两个学生听了以后都笑了，决定以后一起学习。",
