  "passageId": "r-science-feedback",
  "passageLevel": 5,
  "title": "Science: The value of making mistakes",
  "passage": "一位老师发现，学生们害怕在课堂上回答问题，因为他们担心自己的错误会被别人发现。为了改变这种情况，老师要求每位学生先独立完成一道题，再与同学交流各自的想法。他不直接公布正确答案，而是让学生说明自己的理由。经过几次活动，学生逐渐意识到，即使答案不正确，分析产生错误的原因也具有意义。有些原来很少发言的学生开始主动参与讨论。老师认为，良好的学习环境应该让人有机会发现并改正错误。",
  "translation": "A teacher notices students are afraid of being wrong. Students solve a problem independently, discuss their reasoning and analyse mistakes before seeing answers. Previously quiet students participate more. A supportive learning environment can make mistakes useful.",
