  "title": "Mystery · The last train 2: A familiar voice",
  "passage": "到了办公室，工作人员检查了包里的物品。其中有一本旧书和一张照片。照片上有两个孩子，年轻人认出其中一个就是自己，而另一个是多年没有联系的朋友。正在这时，他的手机响了。电话里传来一个熟悉的声音：“你还记得我们小时候一起写的故事吗？”年轻人终于明白，包的主人可能就是那位朋友。可是朋友没有告诉他现在在哪里，只说第二天早上会在他们过去常去的地方等他。",
