  "passageLevel": 5,
  "title": "Mystery · Room 305 2: An ordinary explanation",
  "passage": "第二天，一位老人来到酒店，说明那本书是自己的。记者原以为书里记录的是某个重大事件，却发现它只是一本关于当地居民的生活记录。老人过去是一名教师，退休以后开始采访曾经的学生，把他们的经历写下来。因为书里包括个人信息，他担心其他人拿走，所以请家人发信息提醒自己，但家人把信息发给了错误的号码。记者听完后觉得很有意思，决定在得到老人同意以后，采访他并报道这个特别的项目。",
