  "passageId": "r-rel-promise",
  "passageLevel": 5,
  "title": "Relationships: A small promise",
  "passage": "一对朋友计划合作完成一个项目。他们开始时都很有热情，但其中一人常常因为其他事情忘记自己答应的任务。另一人没有马上表达不满，而是不断替他完成工作。时间长了，双方的关系变得紧张。一次交流中，他们终于说明了各自的感受，并重新确定了任务的范围和完成时间。如果不能按计划完成，就必须提前通知对方。这个简单的约定使合作变得稳定，也让他们重新建立了信任。",
  "translation": "Two friends start a project enthusiastically, but one forgets tasks while the other silently covers them. Tension grows. They discuss their feelings, clarify scope and deadlines and agree to give notice if plans change. Trust improves.",
