  "passageId": "r-work-trust",
  "passageLevel": 5,
  "title": "Business: The cost of hiding a problem",
  "passage": "在一个项目进行期间，一位员工发现设备出现了问题。他担心领导认为自己的能力不足，因此没有及时报告，而是试图独立解决。几天以后，问题变得更加严重，导致整个项目不得不停止。领导了解情况后，没有只批评那位员工，而是组织大家分析事件发生的原因。团队发现，过去的评价方式使员工更关注个人表现，而不愿及时报告风险。于是企业调整了相关制度，鼓励员工主动提出问题，并共同寻找解决方案。",
  "translation": "A worker notices equipment trouble but fears looking incapable, so delays reporting. The problem worsens and stops the project. The team discovers evaluation incentives discourage reporting. It revises the system to encourage early reporting and joint solutions.",
